function sk1240_settings(): array { $d=sk1240_defaults(); if(!sk1240_table('city_information_settings_v1240'))return $d; try{$tid=sk1240_tid();$q=db()->prepare('SELECT * FROM city_information_settings_v1240 WHERE tenant_id IN (0,?) ORDER BY tenant_id DESC LIMIT 1');$q->execute([$tid]);return array_merge($d,$q->fetch()?:[]);}catch(Throwable $e){return $d;} }
