function sk1240_save_section(array $d): void { $key=preg_replace('/[^a-z0-9_\-]/i','',(string)($d['section_key']??''));if($key==='')throw new InvalidArgumentException('Invalid section.');$tid=sk1240_tid();if($tid<1)$tid=0;$base=[];foreach(sk1240_sections(true) as $s)if((string)$s['section_key']===$key){$base=$s;break;}if(!$base)throw new RuntimeException('Section not found.');db()->prepare('INSERT INTO city_information_sections_v1240(tenant_id,section_key,title,subtitle,sort_order,enabled,updated_at) VALUES(?,?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title),subtitle=VALUES(subtitle),sort_order=VALUES(sort_order),enabled=VALUES(enabled),updated_at=NOW()')->execute([$tid,$key,mb_substr(trim((string)($d['title']??$base['title'])),0,190),mb_substr(trim((string)($d['subtitle']??$base['subtitle'])),0,700),max(0,min(9999,(int)($d['sort_order']??$base['sort_order']??10))),!empty($d['enabled'])?1:0]); }
